// 1. Normalize input parameters
const input = $input.item.json;

const sessionId = String(input.session_id ?? '').trim();
const requestId = String(input.request_id ?? '').trim();
const email = String(input.customer_email ?? '').trim().toLowerCase();
const orderId = String(input.order_id ?? '').trim();
const issueType = String(input.issue_type ?? '').trim().toUpperCase();
const issueSummary = String(input.issue_summary ?? '').trim();

const customerConfirmed =
  input.customer_confirmed === true;

// 2. Define allowed issue types
const allowedTypes = [
  'DELIVERY_ISSUE',
  'DAMAGED_ITEM',
  'REFUND_REQUEST',
  'COMPENSATION_REQUEST',
  'PAYMENT_DISPUTE',
  'OTHER'
];

// 3. Validate request parameters
const errors = [];

if (!sessionId) {
  errors.push('Session ID is required');
}

if (!requestId) {
  errors.push('Request ID is required');
}

if (
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ||
  email.length > 254
) {
  errors.push('Valid customer email is required');
}

if (!allowedTypes.includes(issueType)) {
  errors.push('Invalid issue type');
}

if (
  issueSummary.length < 10 ||
  issueSummary.length > 1000
) {
  errors.push('Issue summary must be 10-1000 characters');
}

// 4. Determine request status
const dataValid = errors.length === 0;

let requestStatus;

if (!dataValid) {
  requestStatus = 'VALIDATION_FAILED';
} else if (!customerConfirmed) {
  requestStatus = 'PENDING_CONFIRMATION';
} else {
  requestStatus = 'CONFIRMATION_RECEIVED';
}

// 5. Return normalized request
return {
  json: {
    session_id: sessionId,
    request_id: requestId,
    customer_email: email,
    order_id: orderId,
    issue_type: issueType,
    issue_summary: issueSummary,
    customer_confirmed: customerConfirmed,

    data_valid: dataValid,
    request_status: requestStatus,

    validation_passed:
      dataValid && customerConfirmed,

    validation_error: !dataValid
      ? errors.join('; ')
      : !customerConfirmed
        ? 'Customer confirmation is required'
        : ''
  }
};

const request = $('Verify Authorization Consumption').first().json;

const existingRows = $input.all()
  .map(item => item.json)
  .filter(row => row.ticket_id);

const normalize = value =>
  String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');

// Detect explicit compensation intent in a ticket summary
const hasCompensationIntent = summary =>
  /\b(compensation|compensate|reimbursement|reimburse|goodwill credit)\b|赔偿|补偿/i
    .test(String(summary ?? ''));

// Check whether two issue types represent the same request
const isSameIssue = (row, currentRequest) => {
  const existingType = normalize(row.issue_type);
  const requestedType = normalize(currentRequest.issue_type);

  if (existingType === requestedType) {
    return true;
  }

  const isDeliveryCompensationPair =
    [existingType, requestedType].includes('delivery_issue') &&
    [existingType, requestedType].includes('compensation_request');

  if (isDeliveryCompensationPair) {
    return (
      hasCompensationIntent(row.issue_summary) &&
      hasCompensationIntent(currentRequest.issue_summary)
    );
  }

  return false;
};

const duplicate = existingRows.find(row =>
  normalize(row.customer_email) === normalize(request.customer_email) &&
  normalize(row.order_id) === normalize(request.order_id) &&
  normalize(row.ticket_status) === 'open' &&
  isSameIssue(row, request)
);

return [
  {
    json: {
      ...request,
      is_duplicate: Boolean(duplicate),
      existing_ticket_id: duplicate?.ticket_id ?? '',
      existing_notification_status:
        duplicate?.notification_status ?? ''
    }
  }
];

const request = $input.item.json;

// Defensive authorization check
if (
  request.authorization_passed !== true ||
  request.authorization_consumed !== true
) {
  throw new Error(
    'Ticket creation blocked: valid authorization is required.'
  );
}

// Generate UTC timestamp
const now = new Date();
const createdAt = now.toISOString();

// Generate ticket ID
const datePart = createdAt.slice(0, 10).replace(/-/g, '');

const randomPart = (
  Math.random().toString(36).slice(2, 8) +
  Math.random().toString(36).slice(2, 6)
).toUpperCase();

const ticketId = `TKT-${datePart}-${randomPart}`;

// Prepare ticket record
return {
  json: {
    ticket_id: ticketId,
    created_at: createdAt,
    session_id: request.session_id,
    customer_email: request.customer_email,
    order_id: request.order_id,
    issue_type: request.issue_type,
    issue_summary: request.issue_summary,
    ticket_status: 'OPEN',
    notification_status: 'PENDING'
  }
};

// 1. Retrieve the validated request
const request =
  $('Validate Ticket Request').first().json;

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.id != null);

// 2. Standard authorization rejection
function reject(status, message) {
  return [{
    json: {
      success: false,
      ticket_id: '',
      authorization_passed: false,
      session_id: request.session_id,
      request_id: request.request_id,
      status,
      message
    }
  }];
}

// 3. Verify explicit confirmation
if (request.customer_confirmed !== true) {
  return reject(
    'CONFIRMATION_REQUIRED',
    'Explicit customer confirmation is required.'
  );
}

// 4. Verify pending record existence
if (rows.length === 0) {
  return reject(
    'PENDING_NOT_FOUND',
    'No pending support ticket was found. Please prepare a new ticket preview.'
  );
}

if (rows.length !== 1) {
  return reject(
    'AMBIGUOUS_PENDING_TICKET',
    'Multiple pending ticket records were found. Ticket creation has been blocked.'
  );
}

const pending = rows[0];

// 5. Verify session binding
if (pending.session_id !== request.session_id) {
  return reject(
    'SESSION_MISMATCH',
    'The pending ticket does not belong to this session.'
  );
}

// 6. Verify preview version binding
if (
  !String(pending.request_id ?? '').trim() ||
  String(pending.request_id) !==
    String(request.request_id)
) {
  return reject(
    'REQUEST_VERSION_MISMATCH',
    'The support ticket details have changed. Please review the latest preview before confirming.'
  );
}

// 7. Verify authorization status
if (pending.status === 'PREPARED') {
  return reject(
    'PREVIEW_NOT_ACTIVATED',
    'The ticket preview is not ready for confirmation.'
  );
}

if (pending.status === 'CONSUMED') {
  return reject(
    'CONFIRMATION_ALREADY_USED',
    'This confirmation has already been used.'
  );
}

if (pending.status === 'PROCESSING') {
  return reject(
    'TICKET_PROCESSING',
    'Your support ticket is already being processed.'
  );
}

if (pending.status === 'EXPIRED') {
  return reject(
    'CONFIRMATION_EXPIRED',
    'Your confirmation has expired. Please request a new ticket preview.'
  );
}

if (pending.status !== 'PENDING') {
  return reject(
    'INVALID_PENDING_STATUS',
    'This pending ticket is no longer available for confirmation.'
  );
}

// 8. Verify expiration
const expiresAt = Date.parse(
  pending.expires_at ?? ''
);

if (!Number.isFinite(expiresAt)) {
  return reject(
    'INVALID_PENDING_TICKET',
    'The pending ticket has an invalid expiration time.'
  );
}

if (Date.now() >= expiresAt) {
  return reject(
    'CONFIRMATION_EXPIRED',
    'Your confirmation has expired. Please request a new ticket preview.'
  );
}

// 9. Validate stored ticket information
const allowedTypes = [
  'DELIVERY_ISSUE',
  'DAMAGED_ITEM',
  'REFUND_REQUEST',
  'COMPENSATION_REQUEST',
  'PAYMENT_DISPUTE',
  'OTHER'
];

const email = String(
  pending.customer_email ?? ''
).trim();

const summary = String(
  pending.issue_summary ?? ''
).trim();

if (
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ||
  email.length > 254 ||
  !allowedTypes.includes(pending.issue_type) ||
  summary.length < 10 ||
  summary.length > 1000 ||
  !String(pending.preview_markdown ?? '').trim()
) {
  return reject(
    'INVALID_PENDING_TICKET',
    'The stored ticket information is incomplete or invalid.'
  );
}

// 10. Verify business payload consistency
const fields = [
  'customer_email',
  'order_id',
  'issue_type',
  'issue_summary'
];

for (const field of fields) {
  if (
    String(request[field] ?? '') !==
    String(pending[field] ?? '')
  ) {
    return reject(
      'AUTHORIZATION_PAYLOAD_MISMATCH',
      'The ticket details have changed. Please request a new preview.'
    );
  }
}

// 11. Return authorized stored request
return [{
  json: {
    success: true,
    status: 'AUTHORIZED',
    authorization_passed: true,

    pending_ticket_id: pending.id,
    session_id: pending.session_id,
    request_id: pending.request_id,

    customer_email: pending.customer_email,
    order_id: pending.order_id || '',
    issue_type: pending.issue_type,
    issue_summary: pending.issue_summary,
    preview_markdown: pending.preview_markdown,

    customer_confirmed: true,
    validation_passed: true,
    validation_error: '',

    authorized_at: new Date().toISOString()
  }
}];

// 1. Retrieve the authorized request
const authorized =
  $('Verify Authorization').first().json;

// 2. Retrieve updated Data Table records
const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.id != null);

// 3. Standard rejection response
function reject(status, message) {
  return [{
    json: {
      success: false,
      ticket_id: '',
      authorization_consumed: false,
      session_id: authorized.session_id,
      request_id: authorized.request_id,
      status,
      message
    }
  }];
}

// 4. Verify original authorization
if (authorized.authorization_passed !== true) {
  return reject(
    'AUTHORIZATION_REQUIRED',
    'Ticket authorization has not been granted.'
  );
}

// 5. Verify update result
if (rows.length !== 1) {
  return reject(
    'AUTHORIZATION_CONSUMPTION_FAILED',
    'The confirmation could not be reserved. Ticket creation has been blocked.'
  );
}

const updated = rows[0];

// 6. Verify record identity and state
if (
  String(updated.id) !==
    String(authorized.pending_ticket_id) ||
  updated.session_id !== authorized.session_id ||
  updated.status !== 'PROCESSING'
) {
  return reject(
    'AUTHORIZATION_STATE_MISMATCH',
    'The authorization record is invalid.'
  );
}

// 7. Verify preview version
if (
  !String(updated.request_id ?? '').trim() ||
  String(updated.request_id) !==
    String(authorized.request_id)
) {
  return reject(
    'REQUEST_VERSION_MISMATCH',
    'The ticket preview version has changed. Ticket creation has been blocked.'
  );
}

// 8. Verify business payload integrity
const fields = [
  'customer_email',
  'order_id',
  'issue_type',
  'issue_summary',
  'preview_markdown'
];

for (const field of fields) {
  if (
    String(updated[field] ?? '') !==
    String(authorized[field] ?? '')
  ) {
    return reject(
      'AUTHORIZATION_PAYLOAD_MISMATCH',
      'The ticket details have changed. Ticket creation has been blocked.'
    );
  }
}

// 9. Return verified authorization
return [{
  json: {
    ...authorized,
    success: true,
    status: 'AUTHORIZATION_CONSUMED',
    authorization_consumed: true,
    consumed_at: new Date().toISOString()
  }
}];

// 1. Retrieve the original authorized request
const authorized =
  $('Verify Authorization Consumption').first().json;

// 2. Recover the original business result
const resultNodes = [
  'Return Existing Ticket',
  'Return Created Ticket',
  'Return Notification Failed'
];

const executedNodes = resultNodes.filter(
  nodeName => $(nodeName).isExecuted
);

if (executedNodes.length !== 1) {
  throw new Error(
    'Expected exactly one support ticket result.'
  );
}

const businessResult =
  $(executedNodes[0]).first().json;

// 3. Validate the original business result
if (
  !businessResult ||
  businessResult.success !== true ||
  !['CREATED', 'ALREADY_EXISTS'].includes(
    businessResult.status
  ) ||
  !String(businessResult.ticket_id ?? '').trim()
) {
  throw new Error(
    'Unable to recover a valid support ticket result.'
  );
}

// 4. Retrieve authorization update results
const rows = $input.all()
  .map(item => item.json);

// 5. Verify authorization finalization
const finalized =
  rows.length === 1 &&
  !rows[0].error &&
  rows[0].id != null &&
  String(rows[0].id) ===
    String(authorized.pending_ticket_id) &&
  rows[0].session_id === authorized.session_id &&
  String(authorized.request_id ?? '').trim() !== '' &&
  String(rows[0].request_id ?? '') ===
    String(authorized.request_id) &&
  rows[0].status === 'CONSUMED';

// 6. Preserve the original business result
return [{
  json: {
    ...businessResult,

    request_id: authorized.request_id,

    authorization_finalized: finalized,

    authorization_status: finalized
      ? 'CONSUMED'
      : 'FINALIZATION_FAILED',

    authorization_warning: finalized
      ? ''
      : 'Ticket processing completed, but authorization finalization could not be verified. Manual review is required.'
  }
}];

// 1. Retrieve the new ticket preview
const request =
  $('Prepare Ticket Preview').first().json;

// 2. Retrieve existing records
const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.id != null);

// 3. Define rejection response
function reject(status, message) {
  return [{
    json: {
      success: false,
      preparation_allowed: false,
      ticket_id: '',
      session_id: request.session_id,
      request_id: request.request_id,
      status,
      message
    }
  }];
}

// 4. Validate request identity
if (
  !String(request.session_id ?? '').trim() ||
  !String(request.request_id ?? '').trim()
) {
  return reject(
    'INVALID_PREPARATION_REQUEST',
    'A valid session and request ID are required.'
  );
}

// 5. Allow first-time preparation
if (rows.length === 0) {
  return [{
    json: {
      ...request,
      preparation_allowed: true,
      preparation_action: 'INSERT',
      existing_pending_id: null,
      existing_status: null,
      existing_request_id: null
    }
  }];
}

// 6. Reject ambiguous records
if (rows.length !== 1) {
  return reject(
    'AMBIGUOUS_PENDING_TICKET',
    'Multiple pending ticket records were found. Please contact customer support.'
  );
}

const existing = rows[0];

// 7. Verify session ownership
if (existing.session_id !== request.session_id) {
  return reject(
    'SESSION_MISMATCH',
    'The existing request does not belong to this session.'
  );
}

// 8. Protect processing records
if (existing.status === 'PROCESSING') {
  return reject(
    'TICKET_PROCESSING',
    'Your previous support request is still being processed. Please do not submit another request yet.'
  );
}

// 9. Validate existing state
const replaceableStates = [
  'PREPARED',
  'PENDING',
  'CONSUMED',
  'EXPIRED'
];

if (!replaceableStates.includes(existing.status)) {
  return reject(
    'INVALID_PENDING_STATUS',
    'The existing support request is in an invalid state.'
  );
}

// 10. Allow conditional replacement
return [{
  json: {
    ...request,
    preparation_allowed: true,
    preparation_action: 'UPDATE',
    existing_pending_id: existing.id,
    existing_status: existing.status,
    existing_request_id: existing.request_id ?? null
  }
}];

// 1. Retrieve the original preparation request
const request =
  $('Validate Preparation Permission').first().json;

// 2. Retrieve Data Table write results
const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.id != null);

// 3. Define rejection response
function reject(status, message) {
  return [{
    json: {
      success: false,
      save_verified: false,
      ticket_id: '',
      session_id: request.session_id,
      request_id: request.request_id,
      status,
      message
    }
  }];
}

// 4. Verify preparation permission
if (request.preparation_allowed !== true) {
  return reject(
    'PREPARATION_NOT_ALLOWED',
    'Ticket preparation has not been authorized.'
  );
}

// 5. Verify exactly one record was saved
if (rows.length !== 1) {
  return reject(
    'PENDING_SAVE_FAILED',
    'The ticket preview could not be saved reliably.'
  );
}

const saved = rows[0];

// 6. Verify the saved record identity
if (
  saved.session_id !== request.session_id ||
  String(saved.request_id ?? '') !==
    String(request.request_id)
) {
  return reject(
    'PENDING_SAVE_VERSION_MISMATCH',
    'The saved ticket preview does not match the current request.'
  );
}

// 7. Verify the updated record ID
if (
  request.preparation_action === 'UPDATE' &&
  String(saved.id) !==
    String(request.existing_pending_id)
) {
  return reject(
    'PENDING_SAVE_ID_MISMATCH',
    'The updated ticket preview record is invalid.'
  );
}

// 8. Verify the authorization state
if (saved.status !== 'PREPARED') {
  return reject(
    'PENDING_SAVE_STATE_MISMATCH',
    'The saved ticket preview has an invalid state.'
  );
}

// 9. Verify business data integrity
const fields = [
  'customer_email',
  'order_id',
  'issue_type',
  'issue_summary',
  'preview_markdown'
];

for (const field of fields) {
  if (
    String(saved[field] ?? '') !==
    String(request[field] ?? '')
  ) {
    return reject(
      'PENDING_SAVE_PAYLOAD_MISMATCH',
      'The saved ticket details do not match the original request.'
    );
  }
}

// 10. Verify expiration time
const expiresAt = Date.parse(saved.expires_at ?? '');

if (
  !Number.isFinite(expiresAt) ||
  Date.now() >= expiresAt
) {
  return reject(
    'INVALID_PENDING_EXPIRATION',
    'The saved ticket preview has an invalid expiration time.'
  );
}

// 11. Return verified preparation result
return [{
  json: {
    ...request,

    success: true,
    save_verified: true,
    status: 'PREPARED',

    pending_ticket_id: saved.id,
    expires_at: saved.expires_at,

    preview_markdown: saved.preview_markdown,
    message: saved.preview_markdown
  }
}];
